test('lateFee grows linearly with days', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    terms: 'NET14',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const fee1day = lateFee(issued, '2026-10-22');
  const fee2day = lateFee(issued, '2026-10-23');
  const fee3day = lateFee(issued, '2026-10-24');

  assert.equal(fee2day > fee1day, true);
  assert.equal(fee3day > fee2day, true);
  assert.equal(Math.abs(fee2day - fee1day * 2) <= 1, true);
  assert.equal(Math.abs(fee3day - fee1day * 3) <= 1, true);
});

