  const daysOverdue = 5;
  const fee = lateFee(partial, '2026-10-26');
  const halfTotal = totals.total / 2;
  const expected = Math.round((halfTotal * 0.04 * daysOverdue) / 100);
  assert.equal(fee, expected);
});

